SELECT 
FROM ai_capsule c
INNER JOIN ai_capsule_revision r
    ON r.id = c.current_revision_id
    AND r.tenant_id = #{tenantId}
    AND r.owner_user_id = #{ownerUserId}
  AND r.owner_subject_type = #{subjectType}
WHERE c.tenant_id = #{tenantId}
  AND c.owner_user_id = #{ownerUserId}
  AND c.owner_subject_type = #{subjectType}
  AND c.del_flag = '0'

    AND c.status = #{query.status}


    AND c.record_type = #{query.recordType}


    AND (c.title LIKE CONCAT('%', #{query.keyword}, '%')
        OR r.content LIKE CONCAT('%', #{query.keyword}, '%'))


    AND FIND_IN_SET(#{query.tag}, c.tags) > 0


    AND c.captured_at >= #{query.from}


    AND c.captured_at <= #{query.to}


    AND c.id IN

        #{explicitId}


ORDER BY c.update_time DESC, c.id DESC

SELECT ,
       r.content,
       r.content_format,
       r.content_hash
FROM ai_capsule c
INNER JOIN ai_capsule_revision r
    ON r.id = c.current_revision_id
    AND r.tenant_id = #{tenantId}
    AND r.owner_user_id = #{ownerUserId}
  AND r.owner_subject_type = #{subjectType}
WHERE c.id = #{id}
  AND c.tenant_id = #{tenantId}
  AND c.owner_user_id = #{ownerUserId}
  AND c.owner_subject_type = #{subjectType}
  AND c.del_flag = '0'
LIMIT 1

SELECT ,
       r.content,
       r.content_format,
       r.content_hash
FROM ai_capsule c
INNER JOIN ai_capsule_revision r
    ON r.id = c.current_revision_id
    AND r.tenant_id = #{tenantId}
    AND r.owner_user_id = #{ownerUserId}
  AND r.owner_subject_type = #{subjectType}
WHERE c.tenant_id = #{tenantId}
  AND c.owner_user_id = #{ownerUserId}
  AND c.owner_subject_type = #{subjectType}
  AND c.status = 'ACTIVE'
  AND c.del_flag = '0'

    AND (c.title LIKE CONCAT('%', #{queryText}, '%')
        OR r.content LIKE CONCAT('%', #{queryText}, '%'))


    AND c.captured_at >= #{from}


    AND c.captured_at <= #{to}


    AND c.record_type = #{recordType}


    AND c.id IN

        #{explicitId}


ORDER BY c.update_time DESC, c.id DESC
LIMIT #{limit}

